from cardio_1 import a, G
a('SSI',[('S','Swiss'),('S','Society for'),('I','Infectious Diseases')],'Société suisse d’infectiologie','<p>Publie les recommandations suisses de prise en charge des infections respiratoires de l’adulte.</p>')
a('CAP',[('C','Community'),('A','Acquired'),('P','Pneumonia')],'Pneumonie acquise en communauté','<p>Terme anglais des recommandations pour la pneumonie contractée hors de l’hôpital.</p>','j18-cap')
a('CRB-65',[('C','Confusion'),('R','Respiratory rate (fréquence respiratoire)'),('B','Blood pressure (pression artérielle)'),('65','âge d’au moins 65 ans')],'Score clinique de gravité de la pneumonie','<p>Outil d’orientation, à intégrer à l’oxygénation et au contexte.</p>','j18-curb')
a('CURB-65',[('C','Confusion'),('U','Urée'),('R','Respiratory rate (fréquence respiratoire)'),('B','Blood pressure (pression artérielle)'),('65','âge d’au moins 65 ans')],'Score de gravité de la pneumonie avec urée','<p>Outil de pronostic ; ne dispense pas d’évaluer l’hypoxémie.</p>','j18-curb')
a('ERS',[('E','European'),('R','Respiratory'),('S','Society')],'Société européenne de pneumologie','<p>Co-auteur des recommandations de 2023 pour les pneumonies communautaires sévères.</p>')
a('ESICM',[('E','European'),('S','Society of'),('I','Intensive'),('C','Care'),('M','Medicine')],'Société européenne de soins intensifs','<p>Co-auteur des recommandations européennes de pneumonie communautaire sévère.</p>')
a('ESCMID',[('E','European'),('S','Society of'),('C','Clinical'),('M','Microbiology and'),('I','Infectious'),('D','Diseases')],'Société européenne de microbiologie et maladies infectieuses','<p>Co-auteur des recommandations de pneumonie communautaire sévère.</p>')
a('ALAT',[('A','Asociación'),('LA','Latinoamericana'),('T','de Tórax')],'Asociación Latinoamericana de Tórax (Association latino-américaine du thorax)','<p>Société savante latino-américaine de pneumologie, coautrice avec l’ERS, l’ESICM et l’ESCMID des recommandations internationales 2023 sur la pneumonie communautaire sévère.</p>')
a('CAPE COD',[('CAPE','Community-Acquired Pneumonia : Evaluation'),('COD','of COrticosteroiDs (non strictement lettre à lettre)')],'Essai CAPE COD (hydrocortisone, 2023)','<p>Essai français à double insu (Dequin et al., New England Journal of Medicine 2023 ; 800 patients de soins intensifs atteints de pneumonie communautaire sévère, choc septique exclu à l’inclusion) : hydrocortisone 200 mg par jour pendant 4 ou 8 jours, puis décroissance, pour une durée totale de 8 ou 14 jours ; mortalité à 28 jours de 6,2 % contre 11,9 % sous placebo.</p>')
a('ESCAPe',[('ESCAPe','nom d’essai (méthylprednisolone prolongée dans la pneumonie communautaire sévère), sans développement lettre à lettre')],'Essai ESCAPe (méthylprednisolone, 2022)','<p>Essai à double insu du Department of Veterans Affairs des États-Unis (Meduri et al., Intensive Care Medicine 2022 ; 586 patients de 42 centres) : méthylprednisolone par voie intraveineuse, 40 mg par jour pendant 7 jours puis décroissance sur un traitement total de 20 jours ; mortalité à 60 jours de 16 % contre 18 % sous placebo, différence non significative.</p>')
a('CAP-START',[('CAP-START','nom d’essai (stratégies d’antibiothérapie empirique de la pneumonie communautaire) ; CAP : Community-Acquired Pneumonia, START non strictement lettre à lettre')],'Essai CAP-START (2015)','<p>Essai néerlandais randomisé par grappes et croisé (Postma et al., New England Journal of Medicine 2015) chez des adultes hospitalisés hors soins intensifs : la bêtalactamine seule n’a pas été inférieure à l’association bêtalactamine et macrolide ni à la fluoroquinolone seule pour la mortalité à 90 jours (9,0 %, 11,1 % et 8,8 %).</p>')
a('J10.0',[('J10.0','code de la classification internationale des maladies, grippe saisonnière avec pneumonie')],'Grippe saisonnière prouvée avec pneumonie','<p>Catégorie de la CIM-10-GM 2024 (inchangée dans la version 2026) distincte du groupe J12 à J18.</p>')
a('J16.0',[('J16.0','code de la classification internationale des maladies, pneumonie à Chlamydia')],'Pneumonie à Chlamydia','<p>Catégorie de la CIM-10-GM 2024 du groupe J16 (pneumonies dues à d’autres micro-organismes). Ce cours l’aborde avec les agents atypiques couverts par les macrolides.</p>')
a('J16.8',[('J16.8','code de la classification internationale des maladies, pneumonie due à d’autres micro-organismes précisés')],'Pneumonie due à d’autres micro-organismes précisés','<p>Catégorie de la CIM-10-GM 2024 du groupe J16 ; elle relève du cours consacré à l’agent en cause.</p>')
a('J69.0',[('J69.0','code de la classification internationale des maladies, pneumopathie due à des aliments ou vomissements')],'Pneumopathie par aspiration','<p>Le codage de l’aspiration ne suppose pas à lui seul l’origine bactérienne.</p>')
a('A48.1',[('A48.1','code de la classification internationale des maladies, légionellose')],'Maladie des légionnaires','<p>Code de la légionellose, à distinguer du code d’une pneumonie d’agent non précisé.</p>')
a('BfArM',[('B','Bundesinstitut'),('f','für'),('Ar','Arzneimittel und'),('M','Medizinprodukte')],'Institut fédéral allemand des médicaments et dispositifs médicaux','<p>Édite la version allemande de la CIM-10-GM utilisée pour vérifier les catégories J12–J18.</p>')
a('REMAP-CAP',[('RE','Randomized Embedded'),('MAP','Multifactorial Adaptive Platform'),('CAP','Community-Acquired Pneumonia')],'Plateforme d’essais adaptatifs pour la pneumonie communautaire','<p>Son domaine corticoïdes, publié en 2025 (Intensive Care Medicine), a comparé chez des adultes de soins intensifs atteints de pneumonie communautaire sévère l’hydrocortisone par voie intraveineuse, 50 mg toutes les 6 heures pendant 7 jours, à l’absence de corticoïde ; le recrutement a été arrêté pour futilité, une amélioration relative de plus de 20 % de la mortalité à 90 jours ayant une probabilité inférieure à 5 %. Il ne justifie pas un emploi systématique chez les malades non sévères.</p>')
